import io
import logging
from threading import Thread

from taf.collectors.core.entities.file_getter import FileGetter
from taf.collectors.core.templates.using import Using
from taf.collectors.core import ExecutionError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class K8sFileGetter(Using("k8s_executor"), FileGetter):
    """
    FileGetter for Kubernetes containers.
    """

    def _open_local_file(self, file_name):
        return io.open(file_name, "wb")

    def get_file(self, source_path, target_path):

        def save_stdout(process, target_path):
            with self._open_local_file(target_path) as local_file:
                while True:
                    data = process.stdout.read(size=2 ** 20)
                    if data == b"":
                        break
                    local_file.write(data)

        logger.debug(
            "getting {source_path!r} into {target_path!r}".format(
                source_path=source_path,
                target_path=target_path))
        process = self._k8s_executor.start("cat '{source_path}'".format(source_path=source_path))
        thread = Thread(
            target=save_stdout,
            args=(process, target_path))
        thread.daemon = True
        thread.start()
        thread.join()
        process.wait()
        stderr_data = process.stderr.read()
        exit_status = process.exit_status
        if exit_status or stderr_data:
            raise ExecutionError(
                stdout="<see '{}'>".format(target_path),
                stderr=stderr_data,
                exit_status=exit_status)
